entries.formula:
FAST_N := 12;
SLOW_N := 26;
SIGNAL_N := 9;
FAST := EMA(C, FAST_N);
SLOW := EMA(C, SLOW_N);
DIF: FAST - SLOW, COLOR60A5FA;
DEA: EMA(DIF, SIGNAL_N), COLORF59E0B;
MACD: (DIF - DEA) * 2, STICK, COLORRED;

N := 20;
UPPER := HHV(H, N);
BREAK_UP: CROSS(C, UPPER);
BUY_ICON: DRAWICON(BREAK_UP, L * 0.998, 1), COLOR34D399;
BUY_TXT: DRAWTEXT(BREAK_UP, L * 0.996, 'BUY'), COLOR00C2FF;

entries.example:
REFL: REF(C, 1), DOTLINE;
BASE: MA(C, 20), NODRAW;
COND: IF(C > O, C, 0 / 0), DRAWNULL;

